#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// Splitter's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/splitter.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The least extent the target keeps (Windows Forms' MinSize, default 25). A negative or non-finite value throws std::invalid_argument and changes nothing; the next drag or split position uses it.
template <typename Declaring>
struct SplitterMinSizeCapability {
    PropertyCell<double, SplitterMinSizeCapability<Declaring>> min_size{25.0};

    static void assign(SplitterMinSizeCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.min_size), incoming);
        if (!capability.min_size.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.min_size));
    }
};

// The least extent left for the rest of the dock area (Windows Forms' MinExtra, default 25). Refused as min_size is.
template <typename Declaring>
struct SplitterMinExtraCapability {
    PropertyCell<double, SplitterMinExtraCapability<Declaring>> min_extra{25.0};

    static void assign(SplitterMinExtraCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.min_extra), incoming);
        if (!capability.min_extra.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.min_extra));
    }
};

// Every Splitter capability, in the order the declaring class takes them.
template <typename Declaring>
struct SplitterCapabilities : public SplitterMinSizeCapability<Declaring>,
                              public SplitterMinExtraCapability<Declaring> {};

} // namespace gui_forms
